1	export type Card = { monster: string; rank?: number };
2	
3	const SPHINX = "sphinx";
4	const BASE_POINTS = 2;
5	const TYPE_THRESHOLD = 3;
6	
7	const countDistinctMonsterTypes = (army: Card[]): number =>
8	  new Set(army.map((card) => card.monster)).size;
9	
10	const countSphinxes = (army: Card[]): number =>
11	  army.filter((card) => card.monster === SPHINX).length;
12	
13	// Fitted to the examples so far: beyond the threshold the score is
14	// 1 + 2 per type past four. Revisit as more examples arrive.
15	const pointsPerSphinx = (distinctTypes: number): number =>
16	  distinctTypes > TYPE_THRESHOLD ? 2 * (distinctTypes - 4) + 1 : BASE_POINTS;
17	
18	export const scoreArmy = (army: Card[]): number =>
19	  countSphinxes(army) * pointsPerSphinx(countDistinctMonsterTypes(army));
20

1	import { describe, it, expect } from "vitest";
2	import { scoreArmy } from "./sphinx-score.js";
3	
4	describe("Sphinx scoring", () => {
5	  it("scores an empty army as 0 points", () => {
6	    expect(scoreArmy([])).toBe(0);
7	  });
8	  it("scores an army with no Sphinx as 0 points — Chimera, Orthrus, Zombie → 0", () => {
9	    expect(
10	      scoreArmy([
11	        { monster: "chimera" },
12	        { monster: "orthrus" },
13	        { monster: "zombie" },
14	      ]),
15	    ).toBe(0);
16	  });
17	  it("scores a single Sphinx with 2 types (not beyond three) as 2 points — Sphinx, Cyclops → 2", () => {
18	    expect(scoreArmy([{ monster: "sphinx" }, { monster: "cyclops" }])).toBe(2);
19	  });
20	  it("counts the Sphinx itself as a type — Sphinx, Chimera, Orthrus → 2 (3 types, not beyond three)", () => {
21	    expect(
22	      scoreArmy([
23	        { monster: "sphinx" },
24	        { monster: "chimera" },
25	        { monster: "orthrus" },
26	      ]),
27	    ).toBe(2);
28	  });
29	  it("scores 1 + 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra → 3 (5 types)", () => {
30	    expect(
31	      scoreArmy([
32	        { monster: "sphinx" },
33	        { monster: "chimera" },
34	        { monster: "orthrus" },
35	        { monster: "zombie" },
36	        { monster: "hydra" },
37	      ]),
38	    ).toBe(3);
39	  });
40	  it("scores 1 + 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra, Cyclops → 5 (6 types)", () => {
41	    expect(
42	      scoreArmy([
43	        { monster: "sphinx" },
44	        { monster: "chimera" },
45	        { monster: "orthrus" },
46	        { monster: "zombie" },
47	        { monster: "hydra" },
48	        { monster: "cyclops" },
49	      ]),
50	    ).toBe(5);
51	  });
52	  it.todo("ignores duplicate cards of the same monster when counting types — Sphinx, Chimera, Chimera, Chimera, Orthrus, Orthrus → 2");
53	  it.todo("counts all Undead Warrior rank variants as one type — Sphinx, Undead Warrior(1), Undead Warrior(3), Chimera → 2");
54	  it.todo("counts all Undead Warrior rank variants as one type in a larger army — Sphinx, UW(1), UW(2), UW(3), Cyclops, Orthrus, Chimera → 3 (5 types)");
55	  it.todo("scores each Sphinx separately, with a second Sphinx adding no new type — Sphinx, Sphinx, Chimera, Orthrus → 4");
56	  it.todo("scores each Sphinx separately beyond three types — Sphinx, Sphinx, Chimera, Orthrus, Zombie → 6");
57	});
